def execution_context(manifest,summary):
 replay=manifest.get('run_kind')=='offline_replay' or summary.get('execution_mode')=='offline_replay'
 return {'mode':'offline_replay' if replay else 'live_batch',
         'live_api_calls':0 if replay else summary.get('classification_api_calls',0),
         'historical_api_calls':summary.get('historical_classification_api_calls',0) if replay else 0,
         'source_run':manifest.get('source_run'),
         'fresh_local_processing':not replay}


def pending_by_scope(rows):
 counts={'candidate_or_unknown_documents':0,'out_of_scope_documents':0,'candidate_or_unknown_meaningful_unassigned':0,'out_of_scope_meaningful_unassigned':0}
 for row in rows:
  outside=row.get('document_scope',{}).get('candidate_resume') is False
  prefix='out_of_scope' if outside else 'candidate_or_unknown'
  counts[prefix+'_documents']+=1
  counts[prefix+'_meaningful_unassigned']+=row['final_unassigned_meaningful']
 return counts


